"""
apply_day21_fix.py -- small fix for Day 21: 3 tests in tests/test_ocr.py and
tests/test_documents_endpoint.py required PyMuPDF (requirements-ocr.txt) to
actually be installed to pass, but that's an OPTIONAL dependency the Day 21
installer deliberately does NOT install by default. On a machine without it,
those 3 tests failed instead of skipping.

This was a test bug, not an app bug -- the real OCR code (app/services/ocr.py,
app/services/pdf_parser.py) already failed open correctly, which is exactly
why you saw "ocr_skipped_pymupdf_missing" warnings instead of a crash.

Fix: those 3 tests now call pytest.importorskip("pymupdf") first, same
pattern as the hnswlib tests from Day 20. No app code changes at all.

Run this from inside your production-rag project folder:

    python apply_day21_fix.py
"""
import base64
import io
import zipfile
from pathlib import Path

PAYLOAD = """"""

def main() -> int:
    dest = Path.cwd()
    raw = base64.b64decode(PAYLOAD)
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        zf.extractall(dest)
    print("Patched: tests/test_ocr.py, tests/test_documents_endpoint.py")
    print("Re-run: pytest -v")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
